"""Generate docs/SCORING.md from the rubric code so the documentation cannot drift from the formulas.

Run from backend/:  .venv\Scripts\python tools\gen_scoring_doc.py
"""
import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))

from app.scoring import ratings, rubric  # noqa: E402

out = [
    "# Scoring rubric\n",
    "_Generated by `backend/tools/gen_scoring_doc.py` from `app/scoring/rubric.py`. Do not edit by hand._\n",
    f"Rubric version {rubric.VERSION}. **No language model is involved in scoring.** Every number comes from recorded "
    "state, recorded events, or the same exhaustive planner that detects dead ends.\n",
    "## Categories (each scored 0–100)\n",
    "| Category | Weight | What it measures |", "|---|---|---|",
    *[f"| {c.name} | {c.weight:.0%} | {c.measures} |" for c in rubric.CATEGORIES],
    "\n### Formulas\n",
    *[f"- **{c.name}** ({c.weight:.0%}): `{c.formula}`" for c in rubric.CATEGORIES],
    "\n## Overall score\n",
    "`overall = Σ weight × category score`, then capped by the ending:\n",
    *[f"- {k.replace('_', ' ')}: at most **{v}**" for k, v in rubric.ENDING_CAPS.items()],
    "\nBands: " + ", ".join(f"**{name}** ≥ {floor}" if floor else f"**{name}** below {rubric.BANDS[-2][0]}" for floor, name in rubric.BANDS) + ".\n",
    "## Judging decisions fairly\n",
    "Hindsight is not fair, so a decision is never judged by its outcome alone. Each decision is replayed from the moment "
    f"it was made in {ratings.WORLDS} *plausible worlds* that differ only in what the player could not know: the future "
    "chance events, and the true (hidden) stock level (±30 units). The value of an option is the best ending still "
    "reachable afterwards (the same tiers the dead-end detector uses: 3 hospitals fully served, 2 partial, 1 shortfall, "
    "0 missed or safety failure).\n",
    "| Term | Meaning |", "|---|---|",
    "| `ev` | mean tier over the plausible worlds |",
    "| `p_objective` | share of plausible worlds in which hospitals could still be fully served |",
    "| `regret_ev` | best option's `ev` − chosen option's `ev` |",
    f"| rating | **sound** if regret ≤ {ratings.SOUND_MAX_REGRET}; **questionable** if ≤ {ratings.POOR_MIN_REGRET}; **poor** above |",
    "| `warned_by` | advisors who opposed the chosen option at the time, with reasons based on information the player could see |",
    "| `impact` | change in the readiness score (same formulas, delivery projected from verified stock and capacity) between "
    "the decision and the next decision, including events that fired in between |",
    "| unlucky | rated sound, nobody warned against it, and a chance event (probability < 1) that the decision exposed you to "
    "then happened. Bad luck is attributed to the **latest decision that made the event possible**, or, for events nothing "
    "could have prevented, to the decision just before it fired. Also used when a different option happened to do better in "
    "this run's actual world |",
    "| lucky | rated questionable or poor, yet nothing better was reachable in this run's actual world |",
    "\nA *sound* decision can still be warned against and cost points; the report then says so (\"Feasible, but Arjun and Nisha "
    "warned against it…\") rather than calling it good or bad outright.\n",
    "## Losses, opportunities, alternatives\n",
    "- **Avoidable loss**: a harmful event traced to the **latest** decision at which a comparably sound alternative "
    "(within the sound band) would have made the event impossible. Earlier chances to prevent it are listed too. "
    "Chance-dependent events show their probability.",
    "- **Unavoidable / chance**: no earlier decision could have prevented it.",
    "- **Missed opportunity**: a rewarding event that never fired and what earns it, plus units short of the hospitals' "
    "and contract customer's need and which limit (verified stock or transport capacity) bound it.",
    "- **Recommended alternative**: for questionable or poor decisions, the more feasible option; for sound-but-warned decisions "
    "that cost points, the option the warning advisor recommended. Always with the immediate differences.",
    "- **Adaptability** is the share of decisions rated sound from the first setback onward.",
    "\n## What is revealed after the run\n",
    "Only a finished run's report includes the true stock level and how much of it was never verified.\n",
]
path = pathlib.Path(__file__).resolve().parents[2] / "docs" / "SCORING.md"
path.write_text("\n".join(out), encoding="utf-8")
print("wrote", path)
